            cell,
            epoch,
            now_ms,
            now_mono_ms,
            result,
        } => state.alarm_finished(op, (cell, epoch), now_ms, now_mono_ms, result, &mut effects),
        Event::WakeHint { cell } => state.wake_hint(cell, &mut effects),
        Event::WakeHintAt { cell, .. } => state.wake_hint(cell, &mut effects),
